// DOM Elements
document.addEventListener("DOMContentLoaded", () => {
    const themeToggleBtn = document.getElementById("theme-toggle");
    const courseCards = document.querySelectorAll(".course-card");
    const reflectionPanel = document.getElementById("reflection-panel");
    
    // Panel Elements
    const panelIcon = document.getElementById("panel-icon");
    const panelTitle = document.getElementById("panel-title");
    const panelMeta = document.getElementById("panel-meta");
    
    // 4C Tab Elements
    const q1_4c = document.getElementById("q1-4c");
    const a1_4c = document.getElementById("a1-4c");
    const q2_4c = document.getElementById("q2-4c");
    const a2_4c = document.getElementById("a2-4c");
    const q3_4c = document.getElementById("q3-4c");
    const a3_4c = document.getElementById("a3-4c");
    const q4_4c = document.getElementById("q4-4c");
    const a4_4c = document.getElementById("a4-4c");
    
    // Artefak Tab Elements
    const artefak_q1 = document.getElementById("artefak-q1");
    const artefak_a1 = document.getElementById("artefak-a1");
    const artefak_q2 = document.getElementById("artefak-q2");
    const artefak_a2 = document.getElementById("artefak-a2");
    const artefak_q3 = document.getElementById("artefak-q3");
    const artefak_a3 = document.getElementById("artefak-a3");
    const artefak_list = document.getElementById("artefak-list");
    
    // Kaitan Tab Elements
    const kaitan_concept = document.getElementById("kaitan-concept");
    const kaitan_change = document.getElementById("kaitan-change");
    
    // Modal Elements
    const modal = document.getElementById("artifact-modal");
    const closeModalBtns = document.querySelectorAll(".close-modal");
    const modalTitle = document.getElementById("modal-title");
    const modalDocTitle = document.getElementById("mockup-title");
    const modalDocMeta = document.getElementById("mockup-meta");
    const modalDocContent = document.getElementById("mockup-content");
    const modalDescWhy = document.getElementById("modal-desc-why");
    const modalDescSupport = document.getElementById("modal-desc-support");
    const artifactIframe = document.getElementById("artifact-iframe");
    const iframeContainer = document.getElementById("iframe-preview-container");
    const docMockup = document.getElementById("document-mockup");
    
    let activeCourseId = "filosofi";

    // Initialize Theme
    if (localStorage.getItem("theme") === "light") {
        document.body.classList.add("light-theme");
    }

    // Theme Toggle Handler
    themeToggleBtn.addEventListener("click", () => {
        document.body.classList.toggle("light-theme");
        if (document.body.classList.contains("light-theme")) {
            localStorage.setItem("theme", "light");
        } else {
            localStorage.setItem("theme", "dark");
        }
    });

    // Course Card Click Handler
    courseCards.forEach(card => {
        card.addEventListener("click", (e) => {
            const courseId = card.getAttribute("data-course");
            
            // Toggle Active Classes
            courseCards.forEach(c => c.classList.remove("active"));
            card.classList.add("active");
            
            // Load reflection data
            loadCourseReflection(courseId);
            
            // Smooth scroll only on real user click
            if (e && e.isTrusted) {
                const targetSec = document.getElementById("reflection-panel");
                if (targetSec) {
                    targetSec.scrollIntoView({ behavior: "smooth", block: "start" });
                }
            }
        });
        
        // Accessibility Enter Key support
        card.addEventListener("keydown", (e) => {
            if (e.key === "Enter") {
                card.click();
            }
        });
    });

    // Sub-tab Navigation
    const tabButtons = document.querySelectorAll(".detail-tab-btn");
    const tabContents = document.querySelectorAll(".detail-tab-content");

    tabButtons.forEach(btn => {
        btn.addEventListener("click", () => {
            const tabId = btn.getAttribute("data-tab");
            
            tabButtons.forEach(b => b.classList.remove("active"));
            btn.classList.add("active");
            
            tabContents.forEach(c => {
                c.classList.remove("active");
                if (c.id === `tab-content-${tabId}`) {
                    c.classList.add("active");
                }
            });
        });
    });

    // Close Modals
    closeModalBtns.forEach(btn => {
        btn.addEventListener("click", () => {
            modal.classList.remove("show");
            // Clear Iframe
            if (artifactIframe) artifactIframe.src = "";
        });
    });
    
    // Close Modal on click outside content
    modal.addEventListener("click", (e) => {
        if (e.target === modal) {
            modal.classList.remove("show");
            if (artifactIframe) artifactIframe.src = "";
        }
    });

    // Populate dynamic reflection details
    function loadCourseReflection(courseId) {
        const course = coursesData[courseId];
        if (!course) return;
        
        activeCourseId = courseId;
        
        // Show panel if hidden
        reflectionPanel.style.display = "block";
        
        // Reset class list and add current theme class
        reflectionPanel.className = "reflection-panel";
        reflectionPanel.classList.add("course-theme-" + courseId);
        
        setTimeout(() => {
            reflectionPanel.classList.add("show");
        }, 50);

        // Header Title & Icon
        panelTitle.innerText = course.title;
        panelMeta.innerText = `${course.semester} • ${course.sks}`;
        panelIcon.innerHTML = course.icon;
        
        // Update active class on sub-nav links
        const subNavLinks = document.querySelectorAll(".sub-nav-links a[data-sub-course]");
        subNavLinks.forEach(link => {
            if (link.getAttribute("data-sub-course") === courseId) {
                link.classList.add("active");
            } else {
                link.classList.remove("active");
            }
        });
        
        // Tab 1: Refleksi Menyeluruh & Refleksi 4C
        const overallTextContainer = document.getElementById("refleksi-menyeluruh");
        if (overallTextContainer) {
            overallTextContainer.innerText = course.overallReflection;
        }
        
        q1_4c.innerText = course.refleksi4c.connection.q;
        a1_4c.innerText = course.refleksi4c.connection.a;
        
        q2_4c.innerText = course.refleksi4c.challenge.q;
        a2_4c.innerText = course.refleksi4c.challenge.a;
        
        q3_4c.innerText = course.refleksi4c.concept.q;
        a3_4c.innerText = course.refleksi4c.concept.a;
        
        q4_4c.innerText = course.refleksi4c.change.q;
        a4_4c.innerText = course.refleksi4c.change.a;
        
        // Tab 2: Analisis Artefak
        artefak_q1.innerText = "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi?";
        artefak_a1.innerText = course.artefak.a1;
        
        artefak_q2.innerText = "2. Mengapa artefak tersebut yang saya pilih?";
        artefak_a2.innerText = course.artefak.a2;
        
        artefak_q3.innerText = "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?";
        artefak_a3.innerText = course.artefak.a3;
        
        // Render Artifact Cards List
        artefak_list.innerHTML = "";
        course.artefak.files.forEach((file, index) => {
            const card = document.createElement("div");
            card.className = "artefak-item-card";
            card.innerHTML = `
                <div class="artefak-file-icon">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path>
                        <polyline points="14 2 14 8 20 8"></polyline>
                        <line x1="16" y1="13" x2="8" y2="13"></line>
                        <line x1="16" y1="17" x2="8" y2="17"></line>
                        <polyline points="10 9 9 9 8 9"></polyline>
                    </svg>
                </div>
                <div class="artefak-file-info">
                    <div class="artefak-file-name">${file.name}</div>
                    <div class="artefak-file-type">${file.type}</div>
                </div>
                <button class="artefak-view-btn" aria-label="Lihat detail artefak">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <path d="M5 12h14M12 5l7 7-7 7"></path>
                    </svg>
                </button>
            `;
            
            // Add click listener
            card.querySelector(".artefak-view-btn").addEventListener("click", () => {
                openArtifactViewer(file, course.artefak.a2, course.artefak.a3);
            });
            
            artefak_list.appendChild(card);
        });
        
        // Tab 3: Kaitan Praktis
        kaitan_concept.innerText = course.kaitan.concept;
        kaitan_change.innerText = course.kaitan.change;
    }

    // Modal Viewer Handler
    function openArtifactViewer(file, whyText, supportText) {
        modalTitle.innerText = file.title;
        
        if (file.driveUrl) {
            docMockup.style.display = "none";
            iframeContainer.style.display = "block";
            artifactIframe.src = file.driveUrl;
        } else {
            docMockup.style.display = "block";
            iframeContainer.style.display = "none";
            artifactIframe.src = "";
            
            modalDocTitle.innerText = file.title;
            modalDocMeta.innerHTML = `<span>Kode Dokumen: PPG-${activeCourseId.toUpperCase()}-0${Math.floor(Math.random() * 9) + 1}</span><span>${file.meta}</span>`;
            modalDocContent.innerText = file.content;
        }
        
        modalDescWhy.innerText = whyText;
        modalDescSupport.innerText = supportText;
        
        modal.classList.add("show");
    }

    // Dropdown Navigation Handler
    const navDropdownLinks = document.querySelectorAll(".dropdown-menu a[data-nav-course]");
    navDropdownLinks.forEach(link => {
        link.addEventListener("click", (e) => {
            e.preventDefault();
            const courseId = link.getAttribute("data-nav-course");
            const targetCard = document.querySelector(`.course-card[data-course='${courseId}']`);
            if (targetCard) {
                targetCard.click();
                
                // Smooth scroll to the reflection panel
                const targetSec = document.getElementById("reflection-panel");
                if (targetSec) {
                    targetSec.scrollIntoView({ behavior: "smooth", block: "start" });
                }
            }
        });
    });

    // Sub-Navigation Handler
    const subNavLinks = document.querySelectorAll(".sub-nav-links a[data-sub-course]");
    subNavLinks.forEach(link => {
        link.addEventListener("click", (e) => {
            e.preventDefault();
            const courseId = link.getAttribute("data-sub-course");
            const targetCard = document.querySelector(`.course-card[data-course='${courseId}']`);
            if (targetCard) {
                targetCard.click();
                
                // Smooth scroll to the reflection panel
                const targetSec = document.getElementById("reflection-panel");
                if (targetSec) {
                    targetSec.scrollIntoView({ behavior: "smooth", block: "start" });
                }
            }
        });
    });

    // Auto-select first course (Filosofi) on load
    const firstCourse = document.querySelector(".course-card[data-course='filosofi']");
    if (firstCourse) {
        firstCourse.click();
    }
});
